try {
  const allResults = [];

  // ---------------- HELPERS ----------------
  function esc(value) {
    if (value === undefined || value === null) return "";
    return String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&apos;");
  }

  function panFromGstin(gstin) {
    const g = String(gstin || "").trim().toUpperCase();
    return g.length === 15 ? g.substring(2, 12) : "";
  }

  // Today's date in India (IST) as YYYYMMDD
  function getTodayTallyDate() {
    const parts = new Intl.DateTimeFormat("en-GB", {
      timeZone: "Asia/Kolkata",
      year: "numeric",
      month: "2-digit",
      day: "2-digit"
    }).formatToParts(new Date());

    let y = "", m = "", d = "";
    for (const p of parts) {
      if (p.type === "year") y = p.value;
      if (p.type === "month") m = p.value;
      if (p.type === "day") d = p.value;
    }
    const s = `${y}${m}${d}`;
    if (!/^\d{8}$/.test(s)) throw new Error(`Invalid Tally date generated: ${s}`);
    return s;
  }

  const tallyDate = getTodayTallyDate();

  // ---------------- LOOP ----------------
  for (const inputItem of $input.all()) {
    const data = inputItem.json;
    const invLabel = `Invoice ${data.invoice_number || "(no ref)"}`;

    // ---- Company ----
    // Replace the YOUR_... defaults below with your own details, or pass them on the
    // incoming item (data.company_name, data.company_gstin, ...).
    // Name of the company as it exists inside Tally (used to target the company on import)
    const tallyCompanyName = data.tally_company_name || "YOUR_TALLY_COMPANY_NAME";
    // Real legal name (used on the voucher as buyer / consignee)
    const actualCompanyName = data.company_name || "YOUR_COMPANY_NAME";
    const companyGstin = data.company_gstin || "YOUR_COMPANY_GSTIN";
    const companyState = data.company_state || "YOUR_COMPANY_STATE";
    const companyPincode = data.company_pincode || "YOUR_COMPANY_PINCODE";
    // Address lines printed on the voucher. The last two are the LUT number and e-mail.
    const companyAddressLines = Array.isArray(data.company_address_lines)
      ? data.company_address_lines
      : [
          "YOUR_ADDRESS_LINE_1",
          "YOUR_ADDRESS_LINE_2",
          "YOUR_ADDRESS_LINE_3",
          "YOUR_CITY - YOUR_PINCODE",
          "LUT No. YOUR_LUT_NUMBER",
          "E-Mail : YOUR_COMPANY_EMAIL"
        ];
    const costCentreName = data.cost_centre || "Admin";

    // ---- Vendor ----
    const vendorName = String(data.vendor_name || "").trim();
    if (!vendorName) throw new Error(`${invLabel}: vendor_name is missing`);

    const vendorGstin = String(data.vendor_gstin || "").trim();
    const vendorPan = panFromGstin(vendorGstin);
    const vendorState = String(data.vendor_state || "").trim();
    const vendorRegType = vendorGstin ? "Regular" : "Unregistered";
    const applicableFrom = "20260401";

    // ---- Line items / tax ----
    if (!Array.isArray(data.line_items) || data.line_items.length === 0) {
      throw new Error(`${invLabel}: line_items missing or empty`);
    }
    const taxBreakup = Array.isArray(data.tax_breakup) ? data.tax_breakup : [];

    function purchaseLedgerName(item) {
      if (item.ledger_name && String(item.ledger_name).trim()) return String(item.ledger_name).trim();
      if (item.name && String(item.name).trim()) return String(item.name).trim();
      if (data.ledger_hint && String(data.ledger_hint).trim()) return String(data.ledger_hint).trim();
      return "Purchase Ledger"; // NOT "Purchase Accounts": a ledger cannot share a name with a group
    }

    function dutyHeadFor(taxName) {
      const t = String(taxName || "").toUpperCase();
      if (t.includes("CGST")) return "CGST";
      if (t.includes("SGST") || t.includes("UTGST")) return "SGST/UTGST";
      if (t.includes("IGST")) return "IGST";
      return String(taxName || "");
    }

    function taxLedgerName(taxName) {
      const head = dutyHeadFor(taxName);
      if (head === "CGST") return "CGST Input";
      if (head === "SGST/UTGST") return "SGST Input";
      if (head === "IGST") return "IGST Input";
      return String(taxName || "");
    }

    // ================= MASTERS =================
    let ledgerCreationXML = "";

    if (costCentreName) {
      ledgerCreationXML += `
<TALLYMESSAGE xmlns:UDF="TallyUDF">
  <COSTCENTRE NAME="${esc(costCentreName)}" ACTION="Create">
    <NAME>${esc(costCentreName)}</NAME>
    <CATEGORY>Primary Cost Category</CATEGORY>
  </COSTCENTRE>
</TALLYMESSAGE>`;
    }

    ledgerCreationXML += `
<TALLYMESSAGE xmlns:UDF="TallyUDF">
  <LEDGER NAME="${esc(vendorName)}" ACTION="Create">
    <NAME>${esc(vendorName)}</NAME>
    <PARENT>Sundry Creditors</PARENT>
    <ISBILLWISEON>Yes</ISBILLWISEON>
    <AFFECTSSTOCK>No</AFFECTSSTOCK>
  </LEDGER>
</TALLYMESSAGE>
<TALLYMESSAGE xmlns:UDF="TallyUDF">
  <LEDGER NAME="${esc(vendorName)}" ACTION="Alter">
    <NAME>${esc(vendorName)}</NAME>
    <PARENT>Sundry Creditors</PARENT>
    <ISBILLWISEON>Yes</ISBILLWISEON>
    <AFFECTSSTOCK>No</AFFECTSSTOCK>
    <PARTYGSTIN>${esc(vendorGstin)}</PARTYGSTIN>
    <GSTREGISTRATIONTYPE>${vendorRegType}</GSTREGISTRATIONTYPE>
    <INCOMETAXNUMBER>${esc(vendorPan)}</INCOMETAXNUMBER>
    <LEDGSTREGDETAILS.LIST>
      <APPLICABLEFROM>${applicableFrom}</APPLICABLEFROM>
      <GSTREGISTRATIONTYPE>${vendorRegType}</GSTREGISTRATIONTYPE>
      <PLACEOFSUPPLY>${esc(vendorState)}</PLACEOFSUPPLY>
      <GSTIN>${esc(vendorGstin)}</GSTIN>
      <ISOTHTERRITORYASSESSEE>No</ISOTHTERRITORYASSESSEE>
      <CONSIDERPURCHASEFOREXPORT>No</CONSIDERPURCHASEFOREXPORT>
      <ISTRANSPORTER>No</ISTRANSPORTER>
      <ISCOMMONPARTY>No</ISCOMMONPARTY>
    </LEDGSTREGDETAILS.LIST>
    <LEDMAILINGDETAILS.LIST>
      <APPLICABLEFROM>${applicableFrom}</APPLICABLEFROM>
      <MAILINGNAME>${esc(vendorName)}</MAILINGNAME>
      <ADDRESS.LIST TYPE="String">
        <ADDRESS>${esc(data.vendor_address || "")}</ADDRESS>
      </ADDRESS.LIST>
      <STATE>${esc(vendorState)}</STATE>
      <COUNTRY>India</COUNTRY>
      <PINCODE>${esc(data.vendor_pincode || "")}</PINCODE>
    </LEDMAILINGDETAILS.LIST>
  </LEDGER>
</TALLYMESSAGE>`;

    const otherLedgerParents = {};
    data.line_items.forEach(item => {
      const l = purchaseLedgerName(item);
      if (l) otherLedgerParents[l] = "Purchase Accounts";
    });
    taxBreakup.forEach(tax => {
      const l = taxLedgerName(tax.tax_name);
      if (l) otherLedgerParents[l] = "Duties & Taxes";
    });
    otherLedgerParents["Round Off"] = "Indirect Expenses";
    if (data.tds && data.tds.ledger_name) {
      otherLedgerParents[data.tds.ledger_name] = data.tds.ledger_parent || "Duties & Taxes";
    }

    Object.entries(otherLedgerParents).forEach(([name, parent]) => {
      if (name === vendorName) return;
      ledgerCreationXML += `
<TALLYMESSAGE xmlns:UDF="TallyUDF">
  <LEDGER NAME="${esc(name)}" ACTION="Create">
    <NAME>${esc(name)}</NAME>
    <PARENT>${esc(parent)}</PARENT>
    <ISBILLWISEON>No</ISBILLWISEON>
    <AFFECTSSTOCK>No</AFFECTSSTOCK>
  </LEDGER>
</TALLYMESSAGE>`;
    });

    // ================= TOTALS =================
    const lineItemsTotal = data.line_items.reduce((s, i) => s + Number(i.amount || 0), 0);
    const taxTotal = taxBreakup.reduce((s, t) => s + Number(t.amount || 0), 0);
    const tdsAmount = data.tds && data.tds.amount ? Number(data.tds.amount) : 0;
    const netPayable = Number(data.total_amount || 0);

    if (!Number.isFinite(netPayable)) throw new Error(`${invLabel}: invalid total_amount`);

    // ================= GST RATE DETAILS =================
    let rateDetailsXML = "";
    if (taxBreakup.length > 0 && lineItemsTotal > 0) {
      ["CGST", "SGST/UTGST", "IGST"].forEach(head => {
        const match = taxBreakup.find(t => dutyHeadFor(t.tax_name) === head);
        if (!match) return;

        let rate = Number(match.rate_percent);
        if (!Number.isFinite(rate)) {
          rate = (Number(match.amount || 0) / lineItemsTotal) * 100;
        }
        const rateStr = Number.isInteger(rate) ? String(rate) : rate.toFixed(2);

        rateDetailsXML += `
      <RATEDETAILS.LIST>
        <GSTRATEDUTYHEAD>${esc(head)}</GSTRATEDUTYHEAD>
        <GSTRATEVALUATIONTYPE>Based on Value</GSTRATEVALUATIONTYPE>
        <GSTRATE> ${rateStr}</GSTRATE>
      </RATEDETAILS.LIST>`;
      });
      rateDetailsXML += `
      <RATEDETAILS.LIST>
        <GSTRATEDUTYHEAD>Cess</GSTRATEDUTYHEAD>
        <GSTRATEVALUATIONTYPE>&#4; Not Applicable</GSTRATEVALUATIONTYPE>
      </RATEDETAILS.LIST>
      <RATEDETAILS.LIST>
        <GSTRATEDUTYHEAD>State Cess</GSTRATEDUTYHEAD>
        <GSTRATEVALUATIONTYPE>Based on Value</GSTRATEVALUATIONTYPE>
      </RATEDETAILS.LIST>`;
    }

    // ================= LEDGER ENTRIES =================
    const partyEntryXML = `
    <LEDGERENTRIES.LIST>
      <APPROPRIATEFOR>&#4; Not Applicable</APPROPRIATEFOR>
      <LEDGERNAME>${esc(vendorName)}</LEDGERNAME>
      <ISPARTYLEDGER>Yes</ISPARTYLEDGER>
      <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
      <AMOUNT>${netPayable.toFixed(2)}</AMOUNT>
      <CATEGORYALLOCATIONS.LIST>
        <CATEGORY>Primary Cost Category</CATEGORY>
        <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
        <COSTCENTREALLOCATIONS.LIST>
          <NAME>${esc(costCentreName)}</NAME>
          <AMOUNT>${netPayable.toFixed(2)}</AMOUNT>
        </COSTCENTREALLOCATIONS.LIST>
      </CATEGORYALLOCATIONS.LIST>
      <BILLALLOCATIONS.LIST>
        <NAME>${esc(data.invoice_number || "Auto-Ref")}</NAME>
        <BILLTYPE>New Ref</BILLTYPE>
        <AMOUNT>${netPayable.toFixed(2)}</AMOUNT>
      </BILLALLOCATIONS.LIST>
    </LEDGERENTRIES.LIST>`;

    let lineItemsXML = "";
    data.line_items.forEach(item => {
      const amt = Math.abs(Number(item.amount || 0)).toFixed(2);
      lineItemsXML += `
    <LEDGERENTRIES.LIST>
      <LEDGERNAME>${esc(purchaseLedgerName(item))}</LEDGERNAME>
      <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
      <AMOUNT>-${amt}</AMOUNT>
      <BASICUSERDESCRIPTION.LIST TYPE="String">
        <BASICUSERDESCRIPTION>${esc(item.description || item.name || data.ledger_hint || "")}</BASICUSERDESCRIPTION>
      </BASICUSERDESCRIPTION.LIST>
      <CATEGORYALLOCATIONS.LIST>
        <CATEGORY>Primary Cost Category</CATEGORY>
        <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
        <COSTCENTREALLOCATIONS.LIST>
          <NAME>${esc(costCentreName)}</NAME>
          <AMOUNT>-${amt}</AMOUNT>
        </COSTCENTREALLOCATIONS.LIST>
      </CATEGORYALLOCATIONS.LIST>${rateDetailsXML}
    </LEDGERENTRIES.LIST>`;
    });

    let taxXML = "";
    taxBreakup.forEach(tax => {
      const amt = Math.abs(Number(tax.amount || 0)).toFixed(2);
      taxXML += `
    <LEDGERENTRIES.LIST>
      <LEDGERNAME>${esc(taxLedgerName(tax.tax_name))}</LEDGERNAME>
      <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
      <AMOUNT>-${amt}</AMOUNT>
      <CATEGORYALLOCATIONS.LIST>
        <CATEGORY>Primary Cost Category</CATEGORY>
        <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
        <COSTCENTREALLOCATIONS.LIST>
          <NAME>${esc(costCentreName)}</NAME>
          <AMOUNT>-${amt}</AMOUNT>
        </COSTCENTREALLOCATIONS.LIST>
      </CATEGORYALLOCATIONS.LIST>
    </LEDGERENTRIES.LIST>`;
    });

    let tdsXML = "";
    if (data.tds && data.tds.ledger_name && tdsAmount > 0) {
      tdsXML = `
    <LEDGERENTRIES.LIST>
      <LEDGERNAME>${esc(data.tds.ledger_name)}</LEDGERNAME>
      <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
      <AMOUNT>${tdsAmount.toFixed(2)}</AMOUNT>
    </LEDGERENTRIES.LIST>`;
    }

    // ================= BALANCE CHECK + ROUND OFF =================
    const debitSideTotal = lineItemsTotal + taxTotal;
    const creditSideTotal = netPayable + tdsAmount;
    const roundOff = debitSideTotal - creditSideTotal;

    if (Math.abs(roundOff) > 2) {
      throw new Error(
        `${invLabel}: debit/credit gap of Rs.${roundOff.toFixed(2)} is too large to be rounding ` +
        `(Debits=${debitSideTotal.toFixed(2)}, Credits=${creditSideTotal.toFixed(2)}). ` +
        `Check total_amount / TDS data before importing.`
      );
    }

    let roundOffXML = "";
    if (Math.abs(roundOff) > 0.001) {
      const isCredit = roundOff > 0;
      roundOffXML = `
    <LEDGERENTRIES.LIST>
      <LEDGERNAME>Round Off</LEDGERNAME>
      <ISDEEMEDPOSITIVE>${isCredit ? "No" : "Yes"}</ISDEEMEDPOSITIVE>
      <AMOUNT>${isCredit ? "" : "-"}${Math.abs(roundOff).toFixed(2)}</AMOUNT>
    </LEDGERENTRIES.LIST>`;
    }

    // ================= DRIVE LINK UDF =================
    let driveLinkXML = "";
    if (data.drive_link) {
      driveLinkXML = `
    <UDF:VCHNARR_CUSTOMURL.LIST DESC="\`VCHNarr_CustomURL\`" ISLIST="YES" TYPE="String" INDEX="47501">
      <UDF:VCHNARR_CUSTOMURL DESC="\`VCHNarr_CustomURL\`">${esc(data.drive_link)}</UDF:VCHNARR_CUSTOMURL>
    </UDF:VCHNARR_CUSTOMURL.LIST>`;
    }

    const vendorAddressLines = String(data.vendor_address || "")
      .split(",")
      .map(s => s.trim())
      .filter(Boolean);

    // ================= VOUCHER =================
    // Compact one-line tags, no XML comments: Tally reads values literally.
    // DATE / REFERENCEDATE / EFFECTIVEDATE = today's date in IST.
    // Buyer / consignee use the ACTUAL company name, not the Tally company name.
    const voucherXML = `
<TALLYMESSAGE xmlns:UDF="TallyUDF">
  <VOUCHER VCHTYPE="Purchase" ACTION="Create" OBJVIEW="Invoice Voucher View">
    <ADDRESS.LIST TYPE="String">
      ${vendorAddressLines.map(l => `<ADDRESS>${esc(l)}</ADDRESS>`).join("\n      ")}
    </ADDRESS.LIST>
    <BASICBUYERADDRESS.LIST TYPE="String">
      ${companyAddressLines.map(l => `<BASICBUYERADDRESS>${esc(l)}</BASICBUYERADDRESS>`).join("\n      ")}
    </BASICBUYERADDRESS.LIST>
    <DATE>${tallyDate}</DATE>
    <REFERENCEDATE>${tallyDate}</REFERENCEDATE>
    <EFFECTIVEDATE>${tallyDate}</EFFECTIVEDATE>
    <NARRATION>${esc("Original invoice, approval not received. Work done by AI. " + (data.narration || ""))}</NARRATION>
    <VCHENTRYMODE>Accounting Invoice</VCHENTRYMODE>
    <PERSISTEDVIEW>Invoice Voucher View</PERSISTEDVIEW>
    <ISINVOICE>Yes</ISINVOICE>
    <ISOPTIONAL>Yes</ISOPTIONAL>
    <ISCOSTCENTRE>Yes</ISCOSTCENTRE>
    <VOUCHERTYPENAME>Purchase</VOUCHERTYPENAME>
    <PARTYNAME>${esc(vendorName)}</PARTYNAME>
    <PARTYLEDGERNAME>${esc(vendorName)}</PARTYLEDGERNAME>
    <PARTYMAILINGNAME>${esc(vendorName)}</PARTYMAILINGNAME>
    <BASICBASEPARTYNAME>${esc(vendorName)}</BASICBASEPARTYNAME>
    <PARTYGSTIN>${esc(vendorGstin)}</PARTYGSTIN>
    <PARTYPINCODE>${esc(data.vendor_pincode || "")}</PARTYPINCODE>
    <PLACEOFSUPPLY>${esc(vendorState)}</PLACEOFSUPPLY>
    <GSTREGISTRATIONTYPE>${vendorRegType}</GSTREGISTRATIONTYPE>
    <VATDEALERTYPE>${vendorRegType}</VATDEALERTYPE>
    <GSTREGISTRATION TAXTYPE="GST" TAXREGISTRATION="${esc(companyGstin)}">${esc(companyState)} Registration</GSTREGISTRATION>
    <CMPGSTIN>${esc(companyGstin)}</CMPGSTIN>
    <CMPGSTREGISTRATIONTYPE>Regular</CMPGSTREGISTRATIONTYPE>
    <CMPGSTSTATE>${esc(companyState)}</CMPGSTSTATE>
    <STATENAME>${esc(companyState)}</STATENAME>
    <BASICBUYERNAME>${esc(actualCompanyName)}</BASICBUYERNAME>
    <BUYERPINNUMBER>${esc(panFromGstin(companyGstin))}</BUYERPINNUMBER>
    <CONSIGNEEGSTIN>${esc(companyGstin)}</CONSIGNEEGSTIN>
    <CONSIGNEEMAILINGNAME>${esc(actualCompanyName)}</CONSIGNEEMAILINGNAME>
    <CONSIGNEEPINCODE>${esc(companyPincode)}</CONSIGNEEPINCODE>
    <CONSIGNEEPINNUMBER>${esc(panFromGstin(companyGstin))}</CONSIGNEEPINNUMBER>
    <CONSIGNEESTATENAME>${esc(companyState)}</CONSIGNEESTATENAME>
    <CONSIGNEECOUNTRYNAME>India</CONSIGNEECOUNTRYNAME>
    <COUNTRYOFRESIDENCE>India</COUNTRYOFRESIDENCE>
    <REFERENCE>${esc(data.invoice_number || "")}</REFERENCE>
    <COSTCENTRENAME>${esc(costCentreName)}</COSTCENTRENAME>
    <NUMBERINGSTYLE>Auto Retain</NUMBERINGSTYLE>
    <ALLINVENTORYENTRIES.LIST>    </ALLINVENTORYENTRIES.LIST>
    ${partyEntryXML}
    ${lineItemsXML}
    ${taxXML}
    ${tdsXML}
    ${roundOffXML}${driveLinkXML}
  </VOUCHER>
</TALLYMESSAGE>`;

    // SVCURRENTCOMPANY pins both imports to the Tally company named in tallyCompanyName
    // instead of whichever company happens to be active in Tally.
    // The name must match the company name shown in Tally exactly.
    const ledgerEnvelope = `<ENVELOPE>
<HEADER>
  <TALLYREQUEST>Import Data</TALLYREQUEST>
</HEADER>
<BODY>
  <IMPORTDATA>
    <REQUESTDESC>
      <REPORTNAME>All Masters</REPORTNAME>
      <STATICVARIABLES>
        <SVCURRENTCOMPANY>${esc(tallyCompanyName)}</SVCURRENTCOMPANY>
      </STATICVARIABLES>
    </REQUESTDESC>
    <REQUESTDATA>
      ${ledgerCreationXML}
    </REQUESTDATA>
  </IMPORTDATA>
</BODY>
</ENVELOPE>`;

    const voucherEnvelope = `<?xml version="1.0" encoding="UTF-8"?>
<ENVELOPE>
<HEADER>
  <TALLYREQUEST>Import Data</TALLYREQUEST>
</HEADER>
<BODY>
  <IMPORTDATA>
    <REQUESTDESC>
      <REPORTNAME>Vouchers</REPORTNAME>
      <STATICVARIABLES>
        <SVCURRENTCOMPANY>${esc(tallyCompanyName)}</SVCURRENTCOMPANY>
      </STATICVARIABLES>
    </REQUESTDESC>
    <REQUESTDATA>
      ${voucherXML}
    </REQUESTDATA>
  </IMPORTDATA>
</BODY>
</ENVELOPE>`;

    allResults.push({
      json: {
        ledgerXml: ledgerEnvelope,
        voucherXml: voucherEnvelope,
        tallyDateUsed: tallyDate,
        tallyCompanyName,
        actualCompanyName,
        sourceInvoiceDate: data.invoice_date || null,
        invoiceNumber: data.invoice_number || "",
        purchaseLedgerUsed: data.line_items.map(i => purchaseLedgerName(i)),
        lineItemsTotal,
        taxTotal,
        netPayable,
        debitSideTotal,
        creditSideTotal,
        roundOff,
        meta: data
      }
    });
  }

  return allResults;
} catch (err) {
  return [{ json: { error: err.message, stack: err.stack, receivedData: $input.first().json } }];
}

// ------------------------------- CONFIG --------------------------------------
// Company details: replace the YOUR_... placeholders in CONFIG.company with your own.
const CONFIG = {
  company: {
    // Name of the company as it exists inside Tally (used to target the Tally company on import)
    tallyName: "YOUR_TALLY_COMPANY_NAME",
    // Real legal name of the company
    name: "YOUR_COMPANY_NAME",
    displayName: "YOUR_COMPANY_NAME",
    mailingName: "YOUR_COMPANY_NAME",
    gstin: "YOUR_COMPANY_GSTIN",
    state: "YOUR_COMPANY_STATE",
    pincode: "YOUR_COMPANY_PINCODE",
    city: "YOUR_CITY",
    // Printed on the voucher. The last two lines are the LUT number and e-mail.
    addressLines: [
      "YOUR_ADDRESS_LINE_1",
      "YOUR_ADDRESS_LINE_2",
      "YOUR_ADDRESS_LINE_3",
      "YOUR_CITY - YOUR_PINCODE",
      "LUT No. YOUR_LUT_NUMBER",
      "E-Mail : YOUR_COMPANY_EMAIL"
    ]
  },

  defaultCostCentre: "Admin",
  costCategory: "Primary Cost Category",

  // Voucher behaviour
  isOptional: true,
  narrationPrefix: "Original invoice, approval not received. Work done by AI. ",
  numberingStyle: "Auto Retain",
  billType: "New Ref",
  billRefTemplate: "{invoice_number}/{d}.{m}.{yyyy}",

  // Inventory defaults
  defaultStockItem: "",
  defaultUnit: "Qty",
  defaultGodown: "Main Location",
  defaultBatch: "Primary Batch",
  defaultHsn: "",

  // Ledger groups
  debtorsGroup: "Sundry Debtors",
  salesGroup: "Sales Accounts",
  taxGroup: "Duties & Taxes",
  roundOffLedger: "Round Off",
  roundOffGroup: "Indirect Expenses",

  // Master creation switches
  createUnitsAndGodowns: true,
  createCostCentres: true,
  createStockItems: false,
  writeTaxLedgerGstDetails: false,

  // Validation
  roundTolerance: 2,
  strictGstin: true,

  // UDF used for Drive link
  driveLinkUdf: {
    name: "VCHNarr_CustomURL",
    index: 47501,
    type: "String"
  }
};


// ------------------------------ HELPERS --------------------------------------

const STATE_CODES = {
  "01": "Jammu & Kashmir",
  "02": "Himachal Pradesh",
  "03": "Punjab",
  "04": "Chandigarh",
  "05": "Uttarakhand",
  "06": "Haryana",
  "07": "Delhi",
  "08": "Rajasthan",
  "09": "Uttar Pradesh",
  "10": "Bihar",
  "11": "Sikkim",
  "12": "Arunachal Pradesh",
  "13": "Nagaland",
  "14": "Manipur",
  "15": "Mizoram",
  "16": "Tripura",
  "17": "Meghalaya",
  "18": "Assam",
  "19": "West Bengal",
  "20": "Jharkhand",
  "21": "Odisha",
  "22": "Chhattisgarh",
  "23": "Chhattisgarh",
  "24": "Gujarat",
  "26": "Dadra & Nagar Haveli and Daman & Diu",
  "27": "Maharashtra",
  "29": "Karnataka",
  "30": "Goa",
  "31": "Lakshadweep",
  "32": "Kerala",
  "33": "Tamil Nadu",
  "34": "Puducherry",
  "35": "Andaman & Nicobar Islands",
  "36": "Telangana",
  "37": "Andhra Pradesh",
  "38": "Ladakh"
};

const MONTHS = [
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
];

const GSTIN_RE = /^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/;


function esc(str) {
  if (str === undefined || str === null) return "";

  return String(str)
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}


const opt = (tag, val) =>
  (val === undefined || val === null || String(val).trim() === "")
    ? ""
    : `\n    <${tag}>${esc(val)}</${tag}>`;

const hasNum = v =>
  v !== undefined &&
  v !== null &&
  String(v).trim() !== "" &&
  isFinite(Number(String(v).replace(/,/g, "")));

const num = v => Number(String(v).replace(/,/g, ""));

const toPaise = v => {
  if (!hasNum(v)) {
    throw new Error(`Invalid amount: "${v}"`);
  }

  return Math.round(num(v) * 100);
};

const money = p =>
  (p < 0 ? "-" : "") +
  (Math.abs(p) / 100).toFixed(2);

const round2 = n =>
  Math.round(n * 100) / 100;

const fmtRate = n =>
  String(round2(n));

const qtyStr = n =>
  Number.isInteger(n)
    ? n.toFixed(1)
    : String(n);


function toLines(v, splitCommas = false) {
  if (v === undefined || v === null) return [];

  const arr = Array.isArray(v) ? v : [v];

  let out = [];

  arr.forEach(x => {
    String(x)
      .split(/\r?\n/)
      .forEach(l => out.push(l));
  });

  if (
    splitCommas &&
    out.length === 1 &&
    !Array.isArray(v)
  ) {
    out = out[0].split(",");
  }

  return out
    .map(s => s.trim())
    .filter(Boolean);
}


function parseDate(s) {
  const t = String(s || "").trim();

  let m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);

  let y, mo, d;

  if (m) {
    y = +m[1];
    mo = +m[2];
    d = +m[3];
  } else {
    m = t.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/);

    if (m) {
      y = +m[3];
      mo = +m[2];
      d = +m[1];
    }
  }

  if (
    !y ||
    mo < 1 ||
    mo > 12 ||
    d < 1 ||
    d > 31
  ) {
    throw new Error(
      `Invalid invoice_date: "${s}"`
    );
  }

  return {
    y,
    m: mo,
    d
  };
}


const pad2 = n =>
  String(n).padStart(2, "0");

const tallyDate = p =>
  `${p.y}${pad2(p.m)}${pad2(p.d)}`;

const fyStart = p =>
  `${p.m >= 4 ? p.y : p.y - 1}0401`;

const tallyShort = p =>
  `${p.d}-${MONTHS[p.m - 1]}-${String(p.y).slice(2)}`;

const tallyJD = p =>
  Math.round(
    (
      Date.UTC(p.y, p.m - 1, p.d) -
      Date.UTC(1899, 11, 31)
    ) / 86400000
  );


function panFromGstin(g) {
  const s = (g || "")
    .toString()
    .trim()
    .toUpperCase();

  return s.length === 15
    ? s.substring(2, 12)
    : "";
}


function fillTemplate(tpl, invoiceNo, p) {
  return tpl
    .replace(/{invoice_number}/g, invoiceNo)
    .replace(/{yyyy}/g, p.y)
    .replace(/{yy}/g, String(p.y).slice(2))
    .replace(/{mm}/g, pad2(p.m))
    .replace(/{dd}/g, pad2(p.d))
    .replace(/{m}/g, p.m)
    .replace(/{d}/g, p.d);
}


// ---- naming rules ----
function salesLedgerName(item) {
  const heading = (item.name || item.description || "")
    .toString()
    .trim();

  return heading || "Sales Ledger";
}


function dutyHeadFor(taxName) {
  const t = (taxName || "").toUpperCase();

  if (t.includes("CGST")) return "CGST";
  if (t.includes("SGST") || t.includes("UTGST")) {
    return "SGST/UTGST";
  }
  if (t.includes("IGST")) return "IGST";

  return taxName;
}


function taxLedgerName(taxName) {
  const head = dutyHeadFor(taxName);

  if (head === "CGST") return "CGST Output";
  if (head === "SGST/UTGST") return "SGST Output";
  if (head === "IGST") return "IGST Output";

  return taxName;
}


function rateDetailsXML(r, indent) {
  const i = indent;

  const row = (head, type, rate) => `
${i}<RATEDETAILS.LIST>
${i}  <GSTRATEDUTYHEAD>${head}</GSTRATEDUTYHEAD>
${i}  <GSTRATEVALUATIONTYPE>${type}</GSTRATEVALUATIONTYPE>${
    rate === null
      ? ""
      : `
${i}  <GSTRATE> ${fmtRate(rate)}</GSTRATE>`
  }
${i}</RATEDETAILS.LIST>`;

  return (
    row("CGST", "Based on Value", r / 2) +
    row("SGST/UTGST", "Based on Value", r / 2) +
    row("IGST", "Based on Value", r) +
    row("Cess", "&#4; Not Applicable", null) +
    row("State Cess", "Based on Value", null)
  );
}


function udfXML(name, index, type, value) {
  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ""
  ) {
    return "";
  }

  const tag = String(name).toUpperCase();

  const v =
    String(type || "String") === "Number"
      ? ` ${value}`
      : value;

  return `
    <UDF:${tag}.LIST DESC="\`${esc(name)}\`" ISLIST="YES" TYPE="${esc(type || "String")}" INDEX="${esc(index)}">
      <UDF:${tag} DESC="\`${esc(name)}\`">${esc(v)}</UDF:${tag}>
    </UDF:${tag}.LIST>`;
}


// ------------------------- BUILD ONE INVOICE ---------------------------------

function buildInvoice(input) {

  const data = Object.assign({}, input);
  const warnings = [];
  const C = CONFIG;

  const invNo = data.invoice_number
    ? String(data.invoice_number)
    : "";

  const invLabel =
    `Invoice ${invNo || "(no ref)"}`;


  // ---- basic validation ----

  if (
    !data.buyer_name ||
    !String(data.buyer_name).trim()
  ) {
    throw new Error(
      `${invLabel}: buyer_name missing`
    );
  }

  if (
    !Array.isArray(data.line_items) ||
    data.line_items.length === 0
  ) {
    throw new Error(
      `${invLabel}: line_items missing or empty`
    );
  }

  const taxBreakup =
    Array.isArray(data.tax_breakup)
      ? data.tax_breakup
      : [];


  const dt = parseDate(data.invoice_date);

  const vDate = tallyDate(dt);

  const applicableFrom = fyStart(dt);


  // ---- company ----

  const co = C.company;

  // Name of the company as it exists inside Tally
  const tallyCompanyName =
    data.tally_company_name || co.tallyName;

  // Real legal name of the company
  const actualCompanyName =
    data.company_name || co.name;

  const companyGstin =
    data.company_gstin || co.gstin;

  const companyState =
    data.company_state || co.state;

  const companyPincode =
    data.company_pincode || co.pincode;

  const companyCity =
    data.company_city || co.city;

  const companyMailing =
    data.company_mailing_name || co.mailingName;

  const companyAddr =
    toLines(
      data.company_address_lines ||
      co.addressLines
    );

  const dispatchAddr =
    companyAddr.filter(
      l => !/e-?mail/i.test(l)
    );


  // ---- buyer ----

  const buyerName =
    String(data.buyer_name).trim();

  const buyerGstin =
    (data.buyer_gstin || "")
      .toString()
      .trim()
      .toUpperCase();

  if (
    buyerGstin &&
    !GSTIN_RE.test(buyerGstin)
  ) {
    const msg =
      `${invLabel}: buyer_gstin "${buyerGstin}" is not a valid GSTIN format`;

    if (C.strictGstin) {
      throw new Error(msg);
    } else {
      warnings.push(msg);
    }
  }

  const buyerPan =
    panFromGstin(buyerGstin);

  const gstinState =
    buyerGstin.length === 15
      ? (
          STATE_CODES[
            buyerGstin.substring(0, 2)
          ] || ""
        )
      : "";

  const buyerState =
    data.buyer_state || gstinState;

  if (
    data.buyer_state &&
    gstinState &&
    data.buyer_state
      .trim()
      .toLowerCase() !==
      gstinState.toLowerCase()
  ) {
    warnings.push(
      `${invLabel}: buyer_state "${data.buyer_state}" differs from GSTIN state "${gstinState}"`
    );
  }

  const buyerRegType =
    buyerGstin
      ? "Regular"
      : "Unregistered";

  const buyerPincode =
    data.buyer_pincode
      ? String(data.buyer_pincode).trim()
      : "";

  if (
    buyerPincode &&
    !/^\d{6}$/.test(buyerPincode)
  ) {
    warnings.push(
      `${invLabel}: buyer_pincode "${buyerPincode}" is not 6 digits`
    );
  }

  const placeOfSupply =
    data.place_of_supply || buyerState;

  const buyerAddrLines =
    toLines(data.buyer_address, true);

  const billToPlace =
    data.bill_to_place ||
    data.buyer_city ||
    "";

  const shipToPlace =
    data.ship_to_place ||
    billToPlace;

  const isIntra =
    !!(
      placeOfSupply &&
      companyState &&
      placeOfSupply
        .trim()
        .toLowerCase() ===
      companyState
        .trim()
        .toLowerCase()
    );


  const costCentre =
    (
      data.cost_centre !== undefined
        ? data.cost_centre
        : C.defaultCostCentre
    ) || "";


  // ---- amounts ----

  const lines =
    data.line_items.map(
      (it, idx) => {

        if (!hasNum(it.amount)) {
          throw new Error(
            `${invLabel}: line ${idx + 1} has invalid amount "${it.amount}"`
          );
        }

        return {
          it,
          paise: Math.abs(
            toPaise(it.amount)
          )
        };
      }
    );

  const linesP =
    lines.reduce(
      (s, l) => s + l.paise,
      0
    );


  const taxMap = new Map();

  taxBreakup.forEach(t => {

    const p =
      Math.abs(toPaise(t.amount));

    if (p === 0) return;

    const led =
      taxLedgerName(t.tax_name);

    const cur =
      taxMap.get(led) || {
        head: dutyHeadFor(t.tax_name),
        paise: 0
      };

    cur.paise += p;

    taxMap.set(led, cur);
  });


  const taxP =
    [...taxMap.values()]
      .reduce(
        (s, t) => s + t.paise,
        0
      );


  if (
    isIntra &&
    taxMap.has("IGST Output")
  ) {
    warnings.push(
      `${invLabel}: intra-state supply but IGST present`
    );
  }

  if (
    !isIntra &&
    placeOfSupply &&
    (
      taxMap.has("CGST Output") ||
      taxMap.has("SGST Output")
    )
  ) {
    warnings.push(
      `${invLabel}: inter-state supply but CGST/SGST present`
    );
  }


  const tcsP =
    (
      data.tcs &&
      hasNum(data.tcs.amount)
    )
      ? Math.abs(
          toPaise(data.tcs.amount)
        )
      : 0;

  const creditP =
    linesP + taxP + tcsP;

  const netP =
    hasNum(data.total_amount)
      ? toPaise(data.total_amount)
      : Math.round(creditP / 100) * 100;

  const diffP =
    creditP - netP;


  if (
    Math.abs(diffP) >
    C.roundTolerance * 100
  ) {
    throw new Error(
      `${invLabel}: debit/credit gap of Rs.${money(diffP)} is too large to be rounding ` +
      `(lines+tax+tcs=${money(creditP)}, total=${money(netP)}). Check total_amount / TCS data.`
    );
  }


  // effective GST rate

  const invoiceRate =
    linesP > 0
      ? round2((taxP / linesP) * 100)
      : 0;

  const lineRate =
    it =>
      hasNum(it.gst_rate)
        ? num(it.gst_rate)
        : invoiceRate;


  // ---- mode ----

  const itemMode =
    data.voucher_mode
      ? String(data.voucher_mode)
          .toLowerCase() === "item"
      : data.line_items.some(
          i => i.stock_item
        );


  const stockItemOf =
    it => {

      const s =
        (
          it.stock_item ||
          C.defaultStockItem ||
          ""
        )
          .toString()
          .trim();

      if (!s) {
        throw new Error(
          `${invLabel}: Item-mode line "${it.name || ""}" has no stock_item and CONFIG.defaultStockItem is empty`
        );
      }

      return s;
    };


  // ---- cost-centre helper ----

  const cc =
    (
      deemed,
      amt,
      ind = "      "
    ) =>
      costCentre
        ? `
${ind}<CATEGORYALLOCATIONS.LIST>
${ind}  <CATEGORY>${esc(C.costCategory)}</CATEGORY>
${ind}  <ISDEEMEDPOSITIVE>${deemed}</ISDEEMEDPOSITIVE>
${ind}  <COSTCENTREALLOCATIONS.LIST>
${ind}    <NAME>${esc(costCentre)}</NAME>
${ind}    <AMOUNT>${amt}</AMOUNT>
${ind}  </COSTCENTREALLOCATIONS.LIST>
${ind}</CATEGORYALLOCATIONS.LIST>`
        : "";


  // =========================== MASTERS ======================================

  const msg =
    inner => `
<TALLYMESSAGE xmlns:UDF="TallyUDF">${inner}
</TALLYMESSAGE>`;

  let mastersXML = "";


  if (
    costCentre &&
    C.createCostCentres
  ) {

    mastersXML += msg(`
  <COSTCENTRE NAME="${esc(costCentre)}" ACTION="Create">
    <NAME>${esc(costCentre)}</NAME>
    <CATEGORY>${esc(C.costCategory)}</CATEGORY>
  </COSTCENTRE>`);
  }


  if (itemMode) {

    const units = new Set();
    const godowns = new Set();
    const stocks = new Map();


    lines.forEach(({ it }) => {

      const unit =
        it.unit || C.defaultUnit;

      units.add(unit);

      godowns.add(
        it.godown || C.defaultGodown
      );

      const sn =
        stockItemOf(it);

      if (!stocks.has(sn)) {
        stocks.set(
          sn,
          {
            unit,
            hsn:
              it.hsn_code ||
              C.defaultHsn,
            rate:
              lineRate(it),
            it
          }
        );
      }
    });


    if (C.createUnitsAndGodowns) {

      units.forEach(u => {

        mastersXML += msg(`
  <UNIT NAME="${esc(u)}" ACTION="Create">
    <NAME>${esc(u)}</NAME>
    <ISSIMPLEUNIT>Yes</ISSIMPLEUNIT>
  </UNIT>`);
      });


      godowns.forEach(g => {

        mastersXML += msg(`
  <GODOWN NAME="${esc(g)}" ACTION="Create">
    <NAME>${esc(g)}</NAME>
  </GODOWN>`);
      });
    }


    if (C.createStockItems) {

      stocks.forEach((s, name) => {

        const supply =
          s.it.supply_type ||
          (
            String(s.hsn).startsWith("99")
              ? "Services"
              : "Goods"
          );

        mastersXML += msg(`
  <STOCKITEM NAME="${esc(name)}" ACTION="Create">
    <NAME>${esc(name)}</NAME>
    <BASEUNITS>${esc(s.unit)}</BASEUNITS>
    <GSTAPPLICABLE>&#4; Applicable</GSTAPPLICABLE>
    <GSTTYPEOFSUPPLY>${supply}</GSTTYPEOFSUPPLY>${
      s.hsn
        ? `
    <HSNDETAILS.LIST>
      <APPLICABLEFROM>${applicableFrom}</APPLICABLEFROM>
      <HSNCODE>${esc(s.hsn)}</HSNCODE>
    </HSNDETAILS.LIST>`
        : ""
    }
    <GSTDETAILS.LIST>
      <APPLICABLEFROM>${applicableFrom}</APPLICABLEFROM>
      <TAXABILITY>${esc(
        s.it.taxability ||
        (s.rate > 0
          ? "Taxable"
          : "Nil Rated")
      )}</TAXABILITY>
      <STATEWISEDETAILS.LIST>
        <STATENAME>&#4; Any</STATENAME>${rateDetailsXML(
          s.rate,
          "        "
        )}
      </STATEWISEDETAILS.LIST>
    </GSTDETAILS.LIST>
  </STOCKITEM>`);
      });
    }
  }


  // buyer ledger

  mastersXML += msg(`
  <LEDGER NAME="${esc(buyerName)}" ACTION="Create">
    <NAME>${esc(buyerName)}</NAME>
    <PARENT>${esc(C.debtorsGroup)}</PARENT>
    <ISBILLWISEON>Yes</ISBILLWISEON>
    <AFFECTSSTOCK>No</AFFECTSSTOCK>
  </LEDGER>`);


  const gstDetails =
    (
      buyerGstin ||
      buyerState
    )
      ? `
    <LEDGSTREGDETAILS.LIST>
      <APPLICABLEFROM>${applicableFrom}</APPLICABLEFROM>
      <GSTREGISTRATIONTYPE>${buyerRegType}</GSTREGISTRATIONTYPE>${opt(
        "PLACEOFSUPPLY",
        buyerState
      )}${opt("GSTIN", buyerGstin)}
      <ISOTHTERRITORYASSESSEE>No</ISOTHTERRITORYASSESSEE>
      <CONSIDERPURCHASEFOREXPORT>No</CONSIDERPURCHASEFOREXPORT>
      <ISTRANSPORTER>No</ISTRANSPORTER>
      <ISCOMMONPARTY>No</ISCOMMONPARTY>
    </LEDGSTREGDETAILS.LIST>`
      : "";


  const mailDetails =
    (
      buyerAddrLines.length ||
      buyerState ||
      buyerPincode
    )
      ? `
    <LEDMAILINGDETAILS.LIST>
      <APPLICABLEFROM>${applicableFrom}</APPLICABLEFROM>
      <MAILINGNAME>${esc(buyerName)}</MAILINGNAME>
      <ADDRESS.LIST TYPE="String">
        ${buyerAddrLines
          .map(
            l =>
              `<ADDRESS>${esc(l)}</ADDRESS>`
          )
          .join("\n        ")}
      </ADDRESS.LIST>${opt(
        "STATE",
        buyerState
      )}
      <COUNTRY>India</COUNTRY>${opt(
        "PINCODE",
        buyerPincode
      )}
    </LEDMAILINGDETAILS.LIST>`
      : "";


  mastersXML += msg(`
  <LEDGER NAME="${esc(buyerName)}" ACTION="Alter">
    <NAME>${esc(buyerName)}</NAME>
    <PARENT>${esc(C.debtorsGroup)}</PARENT>
    <ISBILLWISEON>Yes</ISBILLWISEON>
    <AFFECTSSTOCK>No</AFFECTSSTOCK>
    <GSTREGISTRATIONTYPE>${buyerRegType}</GSTREGISTRATIONTYPE>${opt(
      "PARTYGSTIN",
      buyerGstin
    )}${opt(
      "INCOMETAXNUMBER",
      buyerPan
    )}${gstDetails}${mailDetails}
  </LEDGER>`);


  // other ledgers

  const otherLedgers = {};

  lines.forEach(({ it }) => {
    otherLedgers[
      salesLedgerName(it)
    ] = {
      parent: C.salesGroup
    };
  });

  taxMap.forEach((t, led) => {
    otherLedgers[led] = {
      parent: C.taxGroup,
      head: t.head
    };
  });

  if (diffP !== 0) {
    otherLedgers[C.roundOffLedger] = {
      parent: C.roundOffGroup
    };
  }

  if (
    data.tcs &&
    data.tcs.ledger_name
  ) {
    otherLedgers[data.tcs.ledger_name] = {
      parent:
        data.tcs.ledger_parent ||
        C.taxGroup
    };
  }


  Object.entries(otherLedgers)
    .forEach(([name, o]) => {

      const gstTags =
        (
          C.writeTaxLedgerGstDetails &&
          [
            "CGST",
            "SGST/UTGST",
            "IGST"
          ].includes(o.head)
        )
          ? `
    <TAXTYPE>GST</TAXTYPE>
    <GSTDUTYHEAD>${o.head}</GSTDUTYHEAD>`
          : "";


      mastersXML += msg(`
  <LEDGER NAME="${esc(name)}" ACTION="Create">
    <NAME>${esc(name)}</NAME>
    <PARENT>${esc(o.parent)}</PARENT>
    <ISBILLWISEON>No</ISBILLWISEON>
    <AFFECTSSTOCK>No</AFFECTSSTOCK>${gstTags}
  </LEDGER>`);
    });


  // =========================== VOUCHER ======================================

  const billRef =
    data.bill_ref ||
    fillTemplate(
      C.billRefTemplate,
      invNo || "Auto-Ref",
      dt
    );

  const netStr =
    money(netP);


  const partyEntryXML = `
    <LEDGERENTRIES.LIST>
      <LEDGERNAME>${esc(buyerName)}</LEDGERNAME>
      <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
      <ISPARTYLEDGER>Yes</ISPARTYLEDGER>
      <AMOUNT>-${netStr}</AMOUNT>${cc(
        "Yes",
        "-" + netStr
      )}
      <BILLALLOCATIONS.LIST>
        <NAME>${esc(billRef)}</NAME>
        <BILLTYPE>${esc(C.billType)}</BILLTYPE>
        <AMOUNT>-${netStr}</AMOUNT>
      </BILLALLOCATIONS.LIST>
    </LEDGERENTRIES.LIST>`;


  const descXML = (it, ind) => {

    const d =
      toLines(it.description);

    return d.length
      ? `
${ind}<BASICUSERDESCRIPTION.LIST TYPE="String">
${ind}  ${d
  .map(
    l =>
      `<BASICUSERDESCRIPTION>${esc(l)}</BASICUSERDESCRIPTION>`
  )
  .join(`\n${ind}  `)}
${ind}</BASICUSERDESCRIPTION.LIST>`
      : "";
  };


  let inventoryXML = "";
  let lineLedgerXML = "";


  lines.forEach(({ it, paise }) => {

    const amt =
      money(paise);

    const r =
      lineRate(it);


    if (itemMode) {

      const stock =
        stockItemOf(it);

      const unit =
        it.unit || C.defaultUnit;

      const qty =
        hasNum(it.quantity) &&
        num(it.quantity) > 0
          ? num(it.quantity)
          : 1;

      const rate =
        hasNum(it.rate)
          ? num(it.rate)
          : (paise / 100) / qty;

      const hsn =
        it.hsn_code ||
        C.defaultHsn;

      const supply =
        it.supply_type ||
        (
          String(hsn).startsWith("99")
            ? "Services"
            : "Goods"
        );

      const taxability =
        it.taxability ||
        (
          r > 0
            ? "Taxable"
            : "Nil Rated"
        );

      const orderNo =
        it.order_no ||
        data.order_no ||
        data.ship_doc_no ||
        "";

      const godown =
        it.godown ||
        C.defaultGodown;

      const batch =
        it.batch ||
        C.defaultBatch;

      const q =
        ` ${qtyStr(qty)} ${unit}`;


      inventoryXML += `
    <ALLINVENTORYENTRIES.LIST>${descXML(
      it,
      "      "
    )}
      <STOCKITEMNAME>${esc(stock)}</STOCKITEMNAME>
      <GSTOVRDNINELIGIBLEITC>&#4; Not Applicable</GSTOVRDNINELIGIBLEITC>
      <GSTOVRDNISREVCHARGEAPPL>&#4; Not Applicable</GSTOVRDNISREVCHARGEAPPL>
      <GSTOVRDNTAXABILITY>${esc(taxability)}</GSTOVRDNTAXABILITY>
      <GSTSOURCETYPE>Stock Item</GSTSOURCETYPE>
      <GSTITEMSOURCE>${esc(stock)}</GSTITEMSOURCE>
      <HSNSOURCETYPE>Stock Item</HSNSOURCETYPE>
      <HSNITEMSOURCE>${esc(stock)}</HSNITEMSOURCE>
      <GSTOVRDNTYPEOFSUPPLY>${supply}</GSTOVRDNTYPEOFSUPPLY>
      <GSTRATEINFERAPPLICABILITY>As per Masters/Company</GSTRATEINFERAPPLICABILITY>${
        hsn
          ? `
      <GSTHSNNAME>${esc(hsn)}</GSTHSNNAME>`
          : ""
      }
      <GSTHSNINFERAPPLICABILITY>As per Masters/Company</GSTHSNINFERAPPLICABILITY>
      <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
