try {
  const results = [];

  const GSTIN_REGEX = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
  const DATE_REGEX = /^\d{4}-\d{2}-\d{2}$/;
  const AMOUNT_TOLERANCE = 1.0;

  function panFromGstin(gstin) {
    const g = (gstin || "").toString().trim().toUpperCase();
    return g.length === 15 ? g.substring(2, 12) : "";
  }

  for (const inputItem of $input.all()) {
    const data = inputItem.json;
    const errors = [];

    const requiredFields = [
      "vendor_name", "buyer_name", "invoice_number", "invoice_date",
      "line_items", "total_amount"
    ];
    if (data.is_invoice === false || String(data.is_invoice).toLowerCase() === "false") {
      errors.push("Document is not an invoice (is_invoice = false)");
    }

    for (const field of requiredFields) {
      const val = data[field];
      const missing = val === undefined || val === null || val === "" ||
        (Array.isArray(val) && val.length === 0);
      if (missing) errors.push(`Missing required field: ${field}`);
    }

    if (data.vendor_gstin && !GSTIN_REGEX.test(data.vendor_gstin.toString().trim().toUpperCase())) {
      errors.push(`vendor_gstin "${data.vendor_gstin}" is not a valid 15-character GSTIN format`);
    }
    if (data.buyer_gstin && !GSTIN_REGEX.test(data.buyer_gstin.toString().trim().toUpperCase())) {
      errors.push(`buyer_gstin "${data.buyer_gstin}" is not a valid 15-character GSTIN format`);
    }

    if (data.vendor_gstin) {
      const derivedPan = panFromGstin(data.vendor_gstin);
      if (data.vendor_pan && data.vendor_pan.toString().trim().toUpperCase() !== derivedPan) {
        errors.push(`vendor_pan "${data.vendor_pan}" does not match PAN derived from vendor_gstin ("${derivedPan}")`);
      }
    }
    if (data.buyer_gstin) {
      const derivedPan = panFromGstin(data.buyer_gstin);
      if (data.buyer_pan && data.buyer_pan.toString().trim().toUpperCase() !== derivedPan) {
        errors.push(`buyer_pan "${data.buyer_pan}" does not match PAN derived from buyer_gstin ("${derivedPan}")`);
      }
    }

    if (data.invoice_date && !DATE_REGEX.test(data.invoice_date.toString().trim())) {
      errors.push(`invoice_date "${data.invoice_date}" is not in YYYY-MM-DD format`);
    }

    const lineItems = Array.isArray(data.line_items) ? data.line_items : [];
    const taxBreakup = Array.isArray(data.tax_breakup) ? data.tax_breakup : [];

    const lineItemsSum = lineItems.reduce((sum, li) => sum + (Number(li.amount) || 0), 0);
    const taxSum = taxBreakup.reduce((sum, t) => sum + (Number(t.amount) || 0), 0);

    if (data.taxable_value !== undefined && data.taxable_value !== null) {
      const diff = Math.abs(lineItemsSum - Number(data.taxable_value));
      if (diff > AMOUNT_TOLERANCE) {
        errors.push(`Line items sum (${lineItemsSum.toFixed(2)}) does not match taxable_value (${data.taxable_value}), diff ${diff.toFixed(2)}`);
      }
    }

    if (data.total_amount !== undefined && data.total_amount !== null) {
      const expectedTotal = lineItemsSum + taxSum;
      const diff = Math.abs(expectedTotal - Number(data.total_amount));
      if (diff > AMOUNT_TOLERANCE) {
        errors.push(`Line items + tax (${expectedTotal.toFixed(2)}) does not match total_amount (${data.total_amount}), diff ${diff.toFixed(2)}`);
      }
    }

    results.push({
      json: {
        ...data,
        validation_status: errors.length === 0 ? "PASS" : "FAIL",
        validation_errors: errors
      }
    });
  }

  return results;
} catch (err) {
  return [{ json: { error: err.message, stack: err.stack, receivedData: $input.all().map(i => i.json) } }];
}

