  const binaryKey = binaryKeys[0];

  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryKey);

  if (!buffer || buffer.length === 0) {
    results.push({
      json: {
        ...item.json,
        qwen_image_status: "FAILED",
        qwen_image_error: "Binary buffer is empty"
      }
    });
    continue;
  }

  const base64 = buffer.toString("base64");

  const binary = item.binary[binaryKey];

  // Recover which attachment this is (the PDF->PNG path loses the json)
  let attachmentKey = item.json.attachment_key;
  let attachmentSafe = item.json.attachment_safe;
  if (!attachmentKey) {
    const nameHint = String(item.json.fileName || (binary && binary.fileName) || '');
    const m = nameHint.match(/^(att_[A-Za-z0-9]+_\d{2})/);
    if (m) {
      attachmentSafe = m[1];
      const hit = $('Tag Extracted Text').all().find(x => x.json.attachment_safe === attachmentSafe);
      if (hit) attachmentKey = hit.json.attachment_key;
    }
  }

  const mimeType = binary.mimeType || "application/octet-stream";
  const fileName = binary.fileName || "invoice";

  // Check actual file signature
  const firstBytes = buffer.subarray(0, 12).toString("hex");

  let detectedType = "UNKNOWN";

  // PNG
  if (firstBytes.startsWith("89504e470d0a1a0a")) {
    detectedType = "PNG";
  }

  // JPEG
  else if (firstBytes.startsWith("ffd8ff")) {
    detectedType = "JPEG";
  }

  // PDF
  else if (buffer.subarray(0, 4).toString() === "%PDF") {
    detectedType = "PDF";
  }

  results.push({
    json: {
      ...item.json,

      attachment_key: attachmentKey,
      attachment_safe: attachmentSafe,

      qwen_image_status: "READY",

      qwen_image_file_name: fileName,
      qwen_image_mime_type: mimeType,

      qwen_image_size_bytes: buffer.length,

      qwen_image_detected_type: detectedType,

      qwen_image_first_bytes: firstBytes,

      qwen_image_base64_length: base64.length,

      qwen_image_base64: base64
    },

    binary: item.binary
  });
}

return results;

