const results = [];
let attachmentSeq = 0;

const MIN_IMAGE_SIZE = 10 * 1024; // 10 KB

for (const item of $input.all()) {
  const binaries = item.binary || {};

  for (const [key, binary] of Object.entries(binaries)) {
    const mimeType = binary.mimeType;

    // ---------------------------------
    // Supported file types
    // ---------------------------------
    const isPDF = mimeType === "application/pdf";

    const isImage =
      mimeType === "image/png" ||
      mimeType === "image/jpeg";

    // Skip unsupported files
    if (!isPDF && !isImage) {
      continue;
    }

    // ---------------------------------
    // Get file size in bytes
    // ---------------------------------
    let fileSizeBytes = 0;

    if (typeof binary.fileSize === "number") {
      fileSizeBytes = binary.fileSize;

    } else if (typeof binary.fileSize === "string") {
      const match = binary.fileSize.match(
        /([\d.]+)\s*(KB|MB|GB|B)/i
      );

      if (match) {
        const size = parseFloat(match[1]);
        const unit = match[2].toUpperCase();

        const multipliers = {
          B: 1,
          KB: 1024,
          MB: 1024 * 1024,
          GB: 1024 * 1024 * 1024,
        };

        fileSizeBytes =
          size * (multipliers[unit] || 1);
      }
    }

    // ---------------------------------
    // Images must be > 10 KB
    // PDFs are always accepted
    // ---------------------------------
    if (isImage && fileSizeBytes <= MIN_IMAGE_SIZE) {
      continue;
    }

    // ---------------------------------
    // Create ONE output item per attachment
    // ---------------------------------
    // Stable, unique id for THIS attachment. It travels with the item all
    // the way to Tally, so nothing has to be matched by position/order.
    const msgId = String(item.json.id || (item.json.headers && item.json.headers['message-id']) || 'msg')
      .replace(/[^A-Za-z0-9]/g, '').slice(0, 40) || 'msg';
    const seq = String(attachmentSeq++).padStart(2, '0');

    results.push({
      json: {
        ...item.json,

        attachment_key: `${msgId}__${seq}`,
        attachment_safe: `att_${msgId}_${seq}`,   // filesystem-safe version

        // Keep original attachment information
        sourceAttachment: key,
        attachmentMimeType: mimeType,
        attachmentFileName: binary.fileName,
        attachmentSize: binary.fileSize,

        // Useful for tracking multiple attachments
        attachmentIndex: results.length,
      },

      // IMPORTANT:
      // Every attachment gets the SAME binary property name.
      binary: {
        data: binary,
      },
    });
  }
}

return results;

