    item?.json?.content?.parts?.[0]?.text ??
    item?.json?.output ??
    item?.json?.response ??
    item?.json?.text ??
    item?.json?.message?.content;

  if (!raw) {
    results.push({
      json: {
        _error: "No model output found in expected fields.",
        _raw: item?.json ?? {}
      }
    });

    continue;
  }

  // Strip code fences from the response.

  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // If Ollama returned extra text, isolate JSON object
  const firstBrace = cleaned.indexOf("{");
  const lastBrace = cleaned.lastIndexOf("}");

  if (firstBrace !== -1 && lastBrace !== -1) {
    cleaned = cleaned.slice(firstBrace, lastBrace + 1);
  }

  // Parse the JSON.

  let data;

  try {
    data = JSON.parse(cleaned);
  } catch (e) {

    results.push({
      json: {
        _error: `JSON parse failed: ${e.message}`,
        _raw: cleaned
      }
    });

    continue;
  }

  // Helpers.

  function normalizeGstin(value) {
    if (
      value === null ||
      value === undefined ||
      value === ""
    ) {
      return null;
    }

    const gstin = String(value)
      .trim()
      .toUpperCase()
      .replace(/\s+/g, "")
      .replace(/[^A-Z0-9]/g, "");

    return gstin || null;
  }


  function normalizeName(value) {
    return String(value || "")
      .toLowerCase()
      .replace(/[^a-z0-9]/g, "");
  }


  function isValidGstin(gstin) {
    if (!gstin) {
      return false;
    }

    return /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][A-Z0-9]Z[A-Z0-9]$/.test(gstin);
  }


  function panFromGstin(gstin) {
    if (!isValidGstin(gstin)) {
      return null;
    }

    return gstin.substring(2, 12);
  }


  function appendNote(note) {
    if (!note) {
      return;
    }

    const existing =
      data.extraction_notes &&
      String(data.extraction_notes).trim();

    data.extraction_notes = existing
      ? `${existing} ${note}`
      : note;
  }


  // Normalise the extracted GSTINs.

  data.vendor_gstin = normalizeGstin(data.vendor_gstin);
  data.buyer_gstin = normalizeGstin(data.buyer_gstin);

  // Drop misread total / zero rows from the line items.
  if (Array.isArray(data.line_items) && data.line_items.length > 1) {
    const num = v => Number(v) || 0;
    const sum = arr => arr.reduce((s, i) => s + num(i.amount), 0);
    const target = num(data.taxable_value);
    const tol = 1;

    // drop zero / empty rows (e.g. "Transportation ... 00")
    const nonZero = data.line_items.filter(i => num(i.amount) !== 0);
    let items = nonZero.length ? nonZero : data.line_items;

    // if the sum is off, drop the one row whose removal makes it match
    if (target && Math.abs(sum(items) - target) > tol) {
      const idx = items.findIndex((_, k) =>
        Math.abs(sum(items.filter((_, j) => j !== k)) - target) <= tol
      );
      if (idx !== -1) {
        appendNote("A line item matching the invoice total was removed as a misread total row.");
        items = items.filter((_, j) => j !== idx);
      }
    }
    data.line_items = items;
  }

  // ---- Your company details ----
  // Add every GSTIN registered to your company.

  const MY_COMPANY_GSTINS = [
    "YOUR_COMPANY_GSTIN",
    "YOUR_COMPANY_GSTIN_2"
  ];

  // Lowercase letters and digits only, no spaces or punctuation. A party whose
  // normalised name contains this text is treated as your company.
  // Example: "Acme Traders Pvt Ltd" -> "acmetraders".
  const MY_COMPANY_NAME_FRAGMENT = "yourcompanyname";


  // Normalise party names.

  const vendorNameNorm =
    normalizeName(data.vendor_name);

  const buyerNameNorm =
    normalizeName(data.buyer_name);


  const vendorGstin =
    data.vendor_gstin;

  const buyerGstin =
    data.buyer_gstin;


  // Is either party your company? (by name)

  const vendorNameIsMyCompany =
    vendorNameNorm.includes(MY_COMPANY_NAME_FRAGMENT);

  const buyerNameIsMyCompany =
    buyerNameNorm.includes(MY_COMPANY_NAME_FRAGMENT);


  // Is either party your company? (by GSTIN)

  const vendorGstinIsMyCompany =
    vendorGstin &&
    MY_COMPANY_GSTINS.includes(vendorGstin);

  const buyerGstinIsMyCompany =
    buyerGstin &&
    MY_COMPANY_GSTINS.includes(buyerGstin);


  // The same GSTIN on both parties is usually an extraction mistake, for example
  // when the vendor's own GSTIN is missing from the document. Don't keep it on both sides.

  const gstinCollision =
    vendorGstin &&
    buyerGstin &&
    vendorGstin === buyerGstin;


  // Resolve the GSTIN collision.

  if (gstinCollision) {

    // Case A: the buyer is your company and the vendor is not.
    // The GSTIN belongs to the buyer, so the vendor GSTIN is cleared.

    if (
      buyerNameIsMyCompany &&
      !vendorNameIsMyCompany
    ) {

      data.vendor_gstin = null;
      data.vendor_pan = null;

      data.buyer_gstin = buyerGstin;
      data.buyer_pan = panFromGstin(buyerGstin);

      appendNote(
        "Same GSTIN appeared for both parties; GSTIN retained for buyer based on buyer party identification and removed from vendor."
      );
    }


    // Case B: the vendor is your company and the buyer is not.
    // The GSTIN belongs to the vendor, so the buyer GSTIN is cleared.

    else if (
      vendorNameIsMyCompany &&
      !buyerNameIsMyCompany
    ) {

      data.buyer_gstin = null;
      data.buyer_pan = null;

      data.vendor_gstin = vendorGstin;
      data.vendor_pan = panFromGstin(vendorGstin);

      appendNote(
        "Same GSTIN appeared for both parties; GSTIN retained for vendor based on vendor party identification and removed from buyer."
      );
    }


    // Case C: neither party is clearly your company.
    // Ownership can't be determined, so both GSTINs are cleared instead of guessing.

    else {

      data.vendor_gstin = null;
      data.buyer_gstin = null;

      data.vendor_pan = null;
      data.buyer_pan = null;

      appendNote(
        "Same GSTIN appeared for both parties and ownership could not be reliably determined; both party GSTINs were set to null."
      );
    }
  }


  // Validate each GSTIN.

  if (
    data.vendor_gstin &&
    !isValidGstin(data.vendor_gstin)
  ) {

    appendNote(
      "Vendor GSTIN was invalid or malformed and was set to null."
    );

    data.vendor_gstin = null;
    data.vendor_pan = null;
  }


  if (
    data.buyer_gstin &&
    !isValidGstin(data.buyer_gstin)
  ) {

    appendNote(
      "Buyer GSTIN was invalid or malformed and was set to null."
    );

    data.buyer_gstin = null;
    data.buyer_pan = null;
  }


  // Derive the PAN from the final GSTIN.

  data.vendor_pan =
    panFromGstin(data.vendor_gstin);

  data.buyer_pan =
    panFromGstin(data.buyer_gstin);


  // Final party classification.

  const finalVendorGstin =
    normalizeGstin(data.vendor_gstin);

  const finalBuyerGstin =
    normalizeGstin(data.buyer_gstin);


  const finalVendorIsMyCompany =
    vendorNameIsMyCompany ||
    (
      finalVendorGstin &&
      MY_COMPANY_GSTINS.includes(finalVendorGstin)
    );


  const finalBuyerIsMyCompany =
    buyerNameIsMyCompany ||
    (
      finalBuyerGstin &&
      MY_COMPANY_GSTINS.includes(finalBuyerGstin)
    );


  // Does the vendor have a GSTIN?

  const vendorHasGstin =
    !!finalVendorGstin;


  // Voucher direction:
  //   your company is the vendor                      -> Sales
  //   your company is the buyer, vendor has a GSTIN   -> Purchase
  //   your company is the buyer, vendor has no GSTIN  -> Journal
  //   neither                                         -> Review

  if (finalVendorIsMyCompany) {

    data.voucher_direction = "Sales";

  } else if (
    finalBuyerIsMyCompany &&
    vendorHasGstin
  ) {

    data.voucher_direction = "Purchase";

  } else if (
    finalBuyerIsMyCompany &&
    !vendorHasGstin
  ) {

    data.voucher_direction = "Journal";

  } else {

    data.voucher_direction = "Review";
  }


  // Final check: never leave the same GSTIN on both parties. Self-billing isn't
  // supported, so the vendor GSTIN is cleared.

  if (
    data.vendor_gstin &&
    data.buyer_gstin &&
    data.vendor_gstin === data.buyer_gstin
  ) {

    data.vendor_gstin = null;
    data.vendor_pan = null;

    appendNote(
      "Duplicate vendor and buyer GSTIN remained after classification; vendor GSTIN was set to null to prevent incorrect party mapping."
    );
  }


  // Recalculate the PAN from the final GSTIN.

  data.vendor_pan =
    panFromGstin(data.vendor_gstin);

  data.buyer_pan =
    panFromGstin(data.buyer_gstin);

  // Everything that identifies THIS attachment travels on the item itself.
  const src = $('Build Ollama Extraction Prompt').itemMatching(idx).json;
  data.drive_file_id = src.drive_file_id;
  data.drive_link = src.drive_link;
  data.sender_email = src.senderEmail;
  data.attachment_key = src.attachment_key;
  data.attachment_file_name = src.attachmentFileName;




  results.push({
    json: data
  });
}


// Return every item. Each item is processed on its own; nothing is merged or dropped.

return results;
